import{d as h,C as t,o as s,c as g,E as a,a3 as n}from"./chunks/framework.D4-ViStF.js";const y=JSON.parse('{"title":"大畜卦","description":"第二十六卦·山天大畜——天在山中，刚健笃实，辉光日新。","frontmatter":{"title":"大畜卦","description":"第二十六卦·山天大畜——天在山中，刚健笃实，辉光日新。","category":"hexagram","aliases":["大畜","山天大畜"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-26.md","filePath":"yijing/hexagrams/hexagram-26.md","lastUpdated":1787730063000}'),u={name:"yijing/hexagrams/hexagram-26.md"},x=h({...u,setup(m){const o=[{id:"youli",term:"有厉",pinyin:"yǒu lì",meaning:"有危险。但利于停止——不是退缩，是在动之前先立志。"},{id:"liyi",term:"利已",pinyin:"lì yǐ",meaning:"利于停止。已，停止。行动之前，先问本心。"},{id:"yushuofu",term:"舆说輹",pinyin:"yú tuō fù",meaning:"车脱下了伏兔（车轴上的销钉）。舆为车，说为脱，輹为车伏兔。主动卸力，时机未到。"},{id:"liangmazhu",term:"良马逐",pinyin:"liáng mǎ zhú",meaning:"良马奔驰追逐。良马出来了，但先练、再跑。"},{id:"xianyuwei",term:"闲舆卫",pinyin:"xián yú wèi",meaning:"娴熟驾驭车驾与护卫。闲为娴熟，舆卫为车驾护卫——真正的内化，是驾驭良马的能力。"},{id:"tongniuzhigu",term:"童牛之牿",pinyin:"tóng niú zhī gù",meaning:"小牛角上的横木。牿，套在牛角上防止顶人的横木——在苗头最小的时候就收住。"},{id:"fenshizhiya",term:"豮豕之牙",pinyin:"fén shǐ zhī yá",meaning:"阉猪的牙。豮豕，阉过的猪，虽凶牙却不伤人——不是治标，是从根上化。"},{id:"hetianzhiqu",term:"何天之衢",pinyin:"hè tiān zhī qú",meaning:"何其通达的天路。衢，四通八达的大路——山打开，道路向所有人开放。"},{id:"bufanzai",term:"不犯灾",pinyin:"bù fàn zāi",meaning:"不触犯灾祸。不是运气好，是一开始就没有乱动。"},{id:"zhongwuyou",term:"中无尤",pinyin:"zhōng wú yóu",meaning:"居中而没有过失。蓄而不发本身就是德。"},{id:"shanghezhi",term:"上合志",pinyin:"shàng hé zhì",meaning:"上与志向相合。方向对了、志合了，才往。"},{id:"youxi",term:"有喜",pinyin:"yǒu xǐ",meaning:"有喜。自己看见自己在飘，这本身就是元吉。"},{id:"youqing",term:"有庆",pinyin:"yǒu qìng",meaning:"有庆。喜是个人的，庆是可以传出去的。"},{id:"daodaxing",term:"道大行",pinyin:"dào dà xíng",meaning:"道大行于天下。不是某一个人的路通了，是道大行。"}],e=[{position:"初九",type:"yang",text:"有厉，利已。",xiang:"有厉利已，不犯灾也。",textModern:"有危险，但利于停止。不是退缩，是在动之前先立志——学易经、写 Dao，先问本心：为什么学、为谁学。",xiangModern:"有厉利已，不犯灾——不是运气好，是一开始就没有乱动。"},{position:"九二",type:"yang",text:"舆说輹。",xiang:"舆说輹，中无尤也。",textModern:"车自己把销钉取下来——不是别人拦你，是主动卸力。时机未到，蓄而不发；蓄而不发本身就是德。",xiangModern:"舆说輹，中无尤——居中，没有过失；主动蓄，不是被动等。"},{position:"九三",type:"yang",text:"良马逐，利艰贞。曰闲舆卫，利有攸往。",xiang:"利有攸往，上合志也。",textModern:"良马出来了，但先练、再跑。良马是核心理论，闲舆卫是真正的内化——没有闲舆卫，良马跑得越快，车厢越容易散架。这条路是艰的，艰是底色，但守正就能走。",xiangModern:"利有攸往，上合志——方向对了、志合了，才往。"},{position:"六四",type:"yin",text:"童牛之牿，元吉。",xiang:"六四元吉，有喜也。",textModern:"在苗头最小的时候就收住——看见自己在飘，主动套上牿。不是被人提醒、不是摔了才知道，是自己看见、自己收住。「初窥门径」这四个字，比任何夸赞都重。",xiangModern:"六四元吉，有喜——自己看见自己在飘，这本身就是元吉。"},{position:"六五",type:"yin",text:"豮豕之牙，吉。",xiang:"六五之吉，有庆也。",textModern:"不是治标，是从根上化。四爻套牿是治标，五爻治本——根是心性不稳，因夸赞、点赞、收藏而窃喜。写文是因为想写，不是因为想被夸；这两者之间的距离，就是心性要走的路。",xiangModern:"六五之吉，有庆——心性稳了，写出的东西自然感染人，喜是个人的，庆是可以传出去的。"},{position:"上九",type:"yang",text:"何天之衢，亨。",xiang:"何天之衢，道大行也。",textModern:"山打开，道路向所有人开放。初九到六五，是往里收；上九，是往外开——蓄到极致不是为了自己收着，是往外开。",xiangModern:"何天之衢，道大行——不是某一个人的路通了，是道大行于天下。"}];return(p,i)=>{const l=t("DaoHexagramViewer"),r=t("DaoHexagramYaoCards"),d=t("DaoKeywordCards");return s(),g("div",null,[a(l,{name:"大畜",fullName:"山天大畜",upper:"☶",lower:"☰",guaCi:"大畜，利贞。不家食，吉。利涉大川。",pinyin:["dà","chù"],element:"土",direction:"东北",insight:"天在山中，蓄养刚健；能止健，不是压制，是养。",guaSlug:"26shantiandachu",lines:e}),i[0]||(i[0]=n("",9)),a(r,{element:"土",guaSlug:"26shantiandachu",glossary:o,items:e}),i[1]||(i[1]=n("",20)),a(d,{title:"字词释义",items:[{term:"大畜",pinyin:["dà","chù"],meaning:"大的蓄养。天在山中，蓄养刚健。"},{term:"不家食",pinyin:["bù","jiā","shí"],meaning:"不在家私食。蓄积的东西不是只给自己用的。"},{term:"輹",pinyin:["fù"],meaning:"车伏兔，车轴上的部件。「舆说輹」即车脱下伏兔、主动卸力。"},{term:"牿",pinyin:["gù"],meaning:"牛角上的横木，防止顶人。「童牛之牿」：在苗头最小时就收住。"},{term:"豮豕",pinyin:["fén","shǐ"],meaning:"阉割过的猪，虽凶牙却不伤人。从根上化。"},{term:"何天之衢",pinyin:["hè","tiān","zhī","qú"],meaning:"何其通达的天路。衢，四通八达的大路。"},{term:"闲舆卫",pinyin:["xián","yú","wèi"],meaning:"娴熟驾驭车驾护卫。闲，娴熟。真正的内化。"},{term:"辉光日新",pinyin:["huī","guāng","rì","xīn"],meaning:"每天都在积累、都在发光。"},{term:"能止健",pinyin:["néng","zhǐ","jiàn"],meaning:"用山的笃实止住天的刚健冲动。"},{term:"多识前言往行",pinyin:["duō","shí","qián","yán","wǎng","xíng"],meaning:"多记取前人的言论与往行，以蓄养德性。"}]}),i[2]||(i[2]=n("",19))])}}});export{y as __pageData,x as default};
